@media (max-width:1100px){
  .dgs-hero-grid,.dgs-comparison-grid{grid-template-columns:1fr;}
  .dgs-services-grid,.testimonials-grid{grid-template-columns:repeat(2,1fr);}
  .dgs-stats-grid{grid-template-columns:repeat(2,1fr);}
  .dgs-logo-row{grid-template-columns:repeat(3,1fr);}
  .dgs-comparison-col:first-child{border-right:0;border-bottom:1px solid rgba(255,255,255,.1);}
}
@media (max-width:760px){
  .dgs-wrap{width:100%!important;max-width:none!important;padding-left:14px!important;padding-right:14px!important;}
  .dgs-section{padding:76px 0;}
  .dgs-section-tight{padding:62px 0;}
  .dgs-hero{padding:70px 0 50px;}
  .dgs-hero h1{font-size:clamp(2.55rem,12vw,3.5rem)!important;line-height:1.04!important;letter-spacing:-.035em!important;}
  .dgs-hero-copy,.dgs-hero-panel{text-align:left!important;}
  .dgs-hero-grid{gap:34px!important;}
  .dgs-hero-proof{grid-template-columns:1fr!important;max-width:none!important;}
  .dgs-btn-row,.dgs-btn{width:100%;}
  .dgs-hero-proof,.dgs-services-grid,.testimonials-grid,.dgs-stats-grid,.process-points{grid-template-columns:1fr;}
  .dgs-logo-row{grid-template-columns:repeat(2,1fr);}
  #portfolio-gallery,#mascot-gallery,#festival-gallery,#mythological-gallery,#product-gallery,#jewellery-gallery,#concept-gallery,#tvc-gallery{columns:1!important;}
  .process-step{padding-left:82px;margin-bottom:48px;}
  .process-num{width:58px;height:58px;}
  .process-num span{font-size:1.25rem;}
  .dgs-process-line{left:29px;}
  .process-card{padding:24px;}
  .dgs-scroll{display:none;}
  .portfolio-lightbox{padding:72px 12px 68px!important;}
  .portfolio-lightbox-content{width:100%!important;height:calc(100vh - 140px)!important;}
  .portfolio-lightbox-close{top:14px!important;right:14px!important;width:42px!important;height:42px!important;}
  .portfolio-lightbox-arrow{top:auto!important;bottom:16px!important;width:44px!important;height:44px!important;transform:none!important;}
  .portfolio-lightbox-arrow:hover,.portfolio-lightbox-arrow:focus{transform:scale(1.05)!important;}
  .portfolio-lightbox-prev{left:calc(50% - 58px)!important;}
  .portfolio-lightbox-next{right:calc(50% - 58px)!important;}
}

